export const title = "How Much Desk Space Do You Need for a Low-Sensitivity Mouse Setup?";
export const metaTitle = "Desk Space for a Low-Sensitivity Mouse Setup";
export const metaDescription = "Measure real mouse travel, hand clearance, cable movement, and keyboard position before choosing a pad for low-sensitivity use.";
